// exceptionIndex evaluates the exception documents of a namespace once and
// indexes structured exception entries by the (short) rule name they exempt.
//
// It returns a mapping from a rule identifier (without deny_/violation_/warn_
// prefix) to the rich results describing the matching exception entries. The
// empty string key holds entries that apply to every rule.
func (e *Engine) exceptionIndex(ctx context.Context, input ast.Value, namespace string, declared map[string]bool) (map[string][]output.Result, error) {
	index := map[string][]output.Result{}

	addCandidates := func(query string) error {
		candidates, qerr := e.evalExceptionCandidates(ctx, input, query)
		if qerr != nil {
			return qerr
		}
		for _, candidate := range candidates {
			result, rules, ok := normalizeExceptionCandidate(candidate)
			if !ok {
				continue
			}
			if len(rules) == 0 {
				rules = []string{""}
			}
			for _, rule := range rules {
				index[rule] = append(index[rule], result)
			}
		}
		return nil
	}

	if declared["exception"] {
		if err := addCandidates(fmt.Sprintf("data.%s.exception", namespace)); err != nil {
			return nil, err
		}
	}
	for _, name := range exceptionDetailRules {
		if declared[name] {
			if err := addCandidates(fmt.Sprintf("data.%s.%s", namespace, name)); err != nil {
				return nil, err
			}
		}
	}
	return index, nil
}
