func (e *Engine) evalExceptionCandidates(ctx context.Context, input ast.Value, query string) ([]map[string]any, error) {
	options := []func(r *rego.Rego){
		rego.ParsedInput(input),
		rego.Query(query),
		rego.Compiler(e.Compiler()),
		rego.Store(e.Store()),
